// MV3 service worker.
//
// Watches the two order-list API endpoints on Taobao / Pinduoduo and captures
// the *real* request (full URL incl. sign, all headers incl. Cookie + anti-content,
// and the POST body). It serializes that exactly like Chrome's
// "Copy as fetch (Node.js)" so it drops into the InventoryHub import textarea and
// works with the existing /api/fetch proxy + pagination helpers unchanged.
//
// Why capture the whole request instead of just cookies: Pinduoduo's `anti-content`
// and Taobao's mtop `sign` are per-session signatures generated by their page JS —
// you cannot regenerate them from cookies. The cookie alone is not enough.

const TARGET_URLS = [
  '*://h5api.m.taobao.com/h5/mtop.taobao.order.queryboughtlistv2*',
  '*://mobile.pinduoduo.com/proxy/api/api/aristotle/order_list_v4*',
];

// Headers Node's fetch rejects or sets itself. Mirrors what Chrome's
// "Copy as fetch (Node.js)" leaves out.
const HEADER_BLOCKLIST = new Set([
  'host',
  'content-length',
  'connection',
  'accept-encoding',
]);

// Wider than TARGET_URLS. This shows order requests that TARGET_URLS misses.
const WATCH_URLS = [
  '*://h5api.m.taobao.com/*',
  '*://mobile.pinduoduo.com/proxy/api/*',
];
const ORDER_PATH = /order|bought/i;

// The query string holds sign and token values. Logs use host and path only.
function hostAndPath(url) {
  const { host, pathname } = new URL(url);
  return host + pathname;
}

console.log('[capture] service worker started');

function platformForUrl(url) {
  if (url.includes('h5api.m.taobao.com')) return 'taobao';
  if (url.includes('mobile.pinduoduo.com')) return 'pinduoduo';
  return null;
}

// requestId -> body string. Set in onBeforeRequest, consumed in onBeforeSendHeaders.
const pendingBodies = new Map();

function decodeRawBody(raw) {
  if (!raw || !raw.length) return undefined;
  const decoder = new TextDecoder('utf-8');
  let out = '';
  for (const chunk of raw) {
    if (chunk.bytes) out += decoder.decode(chunk.bytes, { stream: true });
  }
  out += decoder.decode();
  return out;
}

// Rebuild an application/x-www-form-urlencoded body from parsed formData.
// Note: the mtop `sign` is computed over the *decoded* `data` value, and
// url-encoding round-trips losslessly, so re-encoding here does not break it.
function encodeFormData(formData) {
  const parts = [];
  for (const [key, values] of Object.entries(formData)) {
    for (const v of values) {
      parts.push(`${encodeURIComponent(key)}=${encodeURIComponent(v)}`);
    }
  }
  return parts.join('&');
}

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    const path = hostAndPath(details.url);
    if (!ORDER_PATH.test(path)) return;
    console.log(
      `[capture] saw ${details.method} ${details.type} ${path} initiator=${details.initiator}`
    );
  },
  { urls: WATCH_URLS }
);

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (details.method !== 'POST' || !details.requestBody) return;
    let body;
    if (details.requestBody.raw) {
      body = decodeRawBody(details.requestBody.raw); // PDD: application/json
    } else if (details.requestBody.formData) {
      body = encodeFormData(details.requestBody.formData); // Taobao: urlencoded
    }
    if (body !== undefined) pendingBodies.set(details.requestId, body);
  },
  { urls: TARGET_URLS },
  ['requestBody']
);

chrome.webRequest.onBeforeSendHeaders.addListener(
  (details) => {
    const platform = platformForUrl(details.url);
    if (!platform || details.method !== 'POST') {
      console.log(
        `[capture] skipped ${details.method} ${hostAndPath(details.url)}: only POST is captured`
      );
      return;
    }

    const headers = {};
    for (const h of details.requestHeaders || []) {
      const name = h.name.toLowerCase();
      if (name.startsWith(':')) continue; // HTTP/2 pseudo-headers
      if (HEADER_BLOCKLIST.has(name)) continue;
      if (h.value != null) headers[h.name] = h.value;
    }

    const body = pendingBodies.get(details.requestId);
    pendingBodies.delete(details.requestId);

    const options = { headers, method: 'POST' };
    if (body !== undefined) options.body = body;

    // Same shape as DevTools "Copy as fetch (Node.js)".
    const command = `fetch(${JSON.stringify(details.url)}, ${JSON.stringify(
      options,
      null,
      2
    )})`;

    const record = { command, url: details.url, capturedAt: Date.now() };
    chrome.storage.local.set({ [`capture_${platform}`]: record });
    console.log(
      `[capture] stored ${platform} ${hostAndPath(details.url)} hasBody=${body !== undefined}`
    );
  },
  { urls: TARGET_URLS },
  ['requestHeaders', 'extraHeaders'] // extraHeaders is required to read Cookie
);

// The InventoryHub import page pulls the latest capture on demand.
chrome.runtime.onMessageExternal.addListener((msg, _sender, sendResponse) => {
  if (!msg || msg.type !== 'GET_CAPTURE') return;
  const platform = msg.platform === 'taobao' ? 'taobao' : 'pinduoduo';
  chrome.storage.local.get(`capture_${platform}`, (res) => {
    const record = res[`capture_${platform}`] || null;
    console.log(`[capture] import page asked for ${platform}: found=${!!record}`);
    sendResponse(record);
  });
  return true; // keep the channel open for the async sendResponse
});
